  "test_path": "tests/unit/test_span_filter_bytes_key.py",
  "test": "import pytest
from types import SimpleNamespace
from langfuse.span_filter import is_genai_span

def _make_span(*, attributes=None):
    return SimpleNamespace(instrumentation_scope=None, attributes=attributes)

def test_is_genai_span_bytes_key():
    """Byte keys that decode to a gen_ai.* namespace should be recognized."""
    span = _make_span(attributes={b"gen_ai.request.model": "gpt-4"})
    assert is_genai_span(span) is True

def test_is_genai_span_bytes_key_invalid_utf8():
    """Byte keys that cannot be decoded should be ignored and not cause errors."""
    span = _make_span(attributes={b"\xff\xfe": "value"})
    # Should safely return False without raising
    assert is_genai_span(span) is False"
}
